set-variable.value:
@{
        var path = context.Request.Url.Path.ToLowerInvariant();
        var marker = "/api/projects/${project}/";
        var i = path.IndexOf(marker);
        if (i == -1) { return false; }
        var rest = path.Substring(i + marker.Length);
        var method = context.Request.Method.ToUpperInvariant();
        var rx = new System.Text.RegularExpressions.Regex("^(evaluations|evaluationrules|evaluationtaxonomies|evaluators|evals|datasets|redteams|insights|schedules)(/|$)");
        if (rx.IsMatch(rest)) { return method != "DELETE"; }
        if (System.Text.RegularExpressions.Regex.IsMatch(rest, "^openai/(v1/)?(evals|responses|conversations|files)(/|$)")) { return true; }
        if (method == "GET" && System.Text.RegularExpressions.Regex.IsMatch(rest, "^(agents|deployments)(/|$)")) { return true; }
        if (method == "POST" && System.Text.RegularExpressions.Regex.IsMatch(rest, "^agents/[^/]+/versions$")) {
            return !rest.StartsWith("agents/care-knowledge-agent/");
        }
        return false;
    }
